"""Additive marketplace schema; run only after verified backups."""
from application import conectar_banco
from schema_utils import criar_tabela, criar_sequence

TABLES = {
 'MP_PRODUTO': '''CREATE TABLE MP_PRODUTO (ID_PRODUTO INTEGER NOT NULL PRIMARY KEY, ID_BARBEARIA INTEGER NOT NULL REFERENCES USUARIO(ID_USUARIO), NOME VARCHAR(160) NOT NULL, DESCRICAO BLOB SUB_TYPE TEXT, DETALHES BLOB SUB_TYPE TEXT, CATEGORIA VARCHAR(100), MARCA VARCHAR(100), PRECO DECIMAL(12,2) NOT NULL CHECK(PRECO>0), ESTOQUE INTEGER NOT NULL CHECK(ESTOQUE>=0), ESTOQUE_MINIMO INTEGER DEFAULT 0 NOT NULL CHECK(ESTOQUE_MINIMO>=0), ATIVO SMALLINT DEFAULT 1 NOT NULL, IMAGENS BLOB SUB_TYPE TEXT, PESO DECIMAL(10,3) NOT NULL CHECK(PESO>0), LARGURA DECIMAL(10,2) NOT NULL CHECK(LARGURA>0), ALTURA DECIMAL(10,2) NOT NULL CHECK(ALTURA>0), COMPRIMENTO DECIMAL(10,2) NOT NULL CHECK(COMPRIMENTO>0), CRIADO_EM TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, ATUALIZADO_EM TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL)''',
 'MP_ESTOQUE': '''CREATE TABLE MP_ESTOQUE (ID_MOVIMENTO INTEGER NOT NULL PRIMARY KEY, ID_PRODUTO INTEGER NOT NULL REFERENCES MP_PRODUTO(ID_PRODUTO), ID_USUARIO INTEGER NOT NULL REFERENCES USUARIO(ID_USUARIO), QUANTIDADE INTEGER NOT NULL, TIPO VARCHAR(25) NOT NULL, OBSERVACAO VARCHAR(500), CHAVE VARCHAR(64), HASH_PEDIDO CHAR(64), CRIADO_EM TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, UNIQUE(ID_PRODUTO,CHAVE))''',
 'MP_FAVORITO': '''CREATE TABLE MP_FAVORITO (ID_USUARIO INTEGER NOT NULL REFERENCES USUARIO(ID_USUARIO), ID_PRODUTO INTEGER NOT NULL REFERENCES MP_PRODUTO(ID_PRODUTO), PRIMARY KEY(ID_USUARIO,ID_PRODUTO))''',
 'MP_CARRINHO': '''CREATE TABLE MP_CARRINHO (ID_USUARIO INTEGER NOT NULL REFERENCES USUARIO(ID_USUARIO), ID_PRODUTO INTEGER NOT NULL REFERENCES MP_PRODUTO(ID_PRODUTO), QUANTIDADE INTEGER NOT NULL CHECK(QUANTIDADE>0), PRIMARY KEY(ID_USUARIO,ID_PRODUTO))''',
 'MP_REMETENTE': '''CREATE TABLE MP_REMETENTE (ID_BARBEARIA INTEGER NOT NULL PRIMARY KEY REFERENCES USUARIO(ID_USUARIO), DADOS BLOB SUB_TYPE TEXT NOT NULL)''',
 'MP_COTACAO': '''CREATE TABLE MP_COTACAO (ID_COTACAO CHAR(32) NOT NULL PRIMARY KEY, ID_USUARIO INTEGER NOT NULL REFERENCES USUARIO(ID_USUARIO), ID_BARBEARIA INTEGER NOT NULL REFERENCES USUARIO(ID_USUARIO), HASH_CARRINHO CHAR(64) NOT NULL, CEP CHAR(8) NOT NULL, DADOS BLOB SUB_TYPE TEXT NOT NULL, EXPIRA_EM TIMESTAMP NOT NULL)''',
 'MP_PEDIDO': '''CREATE TABLE MP_PEDIDO (ID_PEDIDO INTEGER NOT NULL PRIMARY KEY, ID_USUARIO INTEGER NOT NULL REFERENCES USUARIO(ID_USUARIO), ID_BARBEARIA INTEGER NOT NULL REFERENCES USUARIO(ID_USUARIO), CHAVE VARCHAR(64) NOT NULL, HASH_PEDIDO CHAR(64) NOT NULL, STATUS VARCHAR(30) NOT NULL, SUBTOTAL DECIMAL(12,2) NOT NULL, FRETE DECIMAL(12,2) NOT NULL, TOTAL DECIMAL(12,2) NOT NULL, RETIRADA SMALLINT NOT NULL, ENDERECO BLOB SUB_TYPE TEXT NOT NULL, ITENS BLOB SUB_TYPE TEXT NOT NULL, COTACAO BLOB SUB_TYPE TEXT, PAGAMENTO_STATUS VARCHAR(30) DEFAULT 'nao_criado' NOT NULL, PAGAMENTO_ID VARCHAR(150), PAGAMENTO_DADOS BLOB SUB_TYPE TEXT, ENTREGA_STATUS VARCHAR(30) DEFAULT 'nao_criada' NOT NULL, ENTREGA_ID VARCHAR(150), ENTREGA_DADOS BLOB SUB_TYPE TEXT, CRIADO_EM TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, ATUALIZADO_EM TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, UNIQUE(ID_USUARIO,CHAVE))''',
 'MP_AVALIACAO': '''CREATE TABLE MP_AVALIACAO (ID_USUARIO INTEGER NOT NULL REFERENCES USUARIO(ID_USUARIO), ID_PRODUTO INTEGER NOT NULL REFERENCES MP_PRODUTO(ID_PRODUTO), NOTA SMALLINT NOT NULL CHECK(NOTA BETWEEN 1 AND 5), COMENTARIO VARCHAR(1000), ATUALIZADO_EM TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, PRIMARY KEY(ID_USUARIO,ID_PRODUTO))''',
 'MP_INTEGRACAO': '''CREATE TABLE MP_INTEGRACAO (ID INTEGER NOT NULL PRIMARY KEY, LIMITE SMALLINT DEFAULT 3 NOT NULL)''',
}

def migrar_marketplace():
    con=conectar_banco();cur=con.cursor()
    try:
        for name,ddl in TABLES.items():
            criar_tabela(cur, name, ddl, con)
        for seq in ('SEQ_MP_PRODUTO','SEQ_MP_ESTOQUE','SEQ_MP_PEDIDO'):
            criar_sequence(cur, seq, con)
        from marketplace_comercial_schema import migrar_comercial
        migrar_comercial(cur, con)
        cur.execute('SELECT ID FROM MP_INTEGRACAO WHERE ID=1')
        if not cur.fetchone():cur.execute('INSERT INTO MP_INTEGRACAO(ID,LIMITE) VALUES(1,3)')
        con.commit()
    except Exception:con.rollback();raise
    finally:cur.close();con.close()
